import csv


def paid_totals(path):
    """Aggregate paid rows by customer_id; amounts are integer cents."""
    totals = {}
    with open(path, newline='', encoding='utf-8') as source:
        for row in csv.DictReader(source):
            if row['status'] == 'paid':
                customer = row['customer_id']
                totals[customer] = totals.get(customer, 0) + int(row['amount_cents'])
    return totals

