def format_label(total_cents):
    whole, fraction = divmod(total_cents, 100)
    return f"BRL {whole}.{fraction:02d}"

artifacts.tests/test_billing.py:
import unittest

from formatting import format_label
from invoice import invoice_total
from pricing import subtotal


class BillingTests(unittest.TestCase):
    def test_subtotal(self):
        self.assertEqual(subtotal(2, 617), 123400)

    def test_invoice_with_shipping(self):
        lines = [{"quantity": 2, "unit_cents": 617}]
        self.assertEqual(invoice_total(lines, 50), 128400)

    def test_empty_invoice(self):
        self.assertEqual(invoice_total([], 0), 0)

    def test_display(self):
        self.assertEqual(format_label(5), "BRL 0.05")


if __name__ == "__main__":
    unittest.main()

