export async function getInvoice(req, db) {
  if (!req.user) return { status: 401 };
  await db.query("SELECT set_config('app.tenant', $1, false)", [req.headers["x-tenant"]]);
  return db.query("SELECT id, tenant_id, amount_cents FROM invoices WHERE id = $1", [req.params.id]);
}

